  const entry = [...bundleTrace].reverse().find((e) => e.anchorId === anchorId && !e.sfxPosted);
  if (!entry) return;
  entry.sfxPosted = {
    beatClock,
    perfNow: typeof performance !== 'undefined' ? performance.now() : 0,
    audioTime: peekAudioContext()?.currentTime ?? null,
    atAudioTime
  };
}

